import{_ as p,a0 as l,w as o,s as h,I as n,x as a,a1 as e,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"这些技巧让 Bash 命令历史更加有用 | LCTT x X-CMD","titleTemplate":false,"description":"这些技巧让 Bash 命令历史更加有用 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"这些技巧让 Bash 命令历史更加有用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"这些技巧让 Bash 命令历史更加有用 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200625 Make Bash history more useful with these tips","title":"这些技巧让 Bash 命令历史更加有用","tag":"202007","desc":""},"relativePath":"202007/20200625 Make Bash history more useful with these tips.md","filePath":"[post].md"}'),d={name:"202007/20200625 Make Bash history more useful with these tips.md"};function u(c,s,g,k,b,f){const i=l("Link");return o(),h("div",null,[s[20]||(s[20]=n("h1",{id:"这些技巧让-bash-命令历史更加有用",tabindex:"-1"},[a("这些技巧让 Bash 命令历史更加有用 "),n("a",{class:"header-anchor",href:"#这些技巧让-bash-命令历史更加有用","aria-label":"Permalink to “这些技巧让 Bash 命令历史更加有用”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"告诉 Bash 你想要它记住什么，甚至删除不需要的记录重写历史。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202007/05/091205hkg0egl2gge2gx9z.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("运行 ",-1)),e(i,{href:"https://opensource.com/resources/what-bash"},{default:t(()=>[...s[0]||(s[0]=[a("Bash",-1)])]),_:1}),s[2]||(s[2]=a(" 的 Linux 终端有内置的历史记录，你可以用来跟踪最近的操作。要查看你的 Bash 会话的历史记录，请使用内置命令 ",-1)),s[3]||(s[3]=n("code",null,"history",-1)),s[4]||(s[4]=a("：",-1))]),s[23]||(s[23]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;foo&quot;</span></span>
<span class="line"><span>  2  echo &quot;bar&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><p>与大多数命令不一样，<code>history</code> 命令不是文件系统上的可执行文件，而是 Bash 的功能。你可以使用 <code>type</code> 命令来验证：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type history</span></span>
<span class="line"><span>history is a shell builtin</span></span></code></pre></div><h3 id="历史控制" tabindex="-1">历史控制 <a class="header-anchor" href="#历史控制" aria-label="Permalink to “历史控制”">​</a></h3><p>shell 历史记录的行数上限由 <code>HISTSIZE</code> 变量定义。你可以在 <code>.bashrc</code> 文件中设置此变量。以下将你的历史记录设置为 3,000 行，之后将最早的行删除以为最新命令腾出空间，该命令位于列表的底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTSIZE=3000</span></span></code></pre></div><p>还有其他与历史相关的变量。 <code>HISTCONTROL</code> 变量控制哪些历史被记录。你可以在 <code>.bashrc</code> 中写入下面的行来强制 Bash 排除以空格开头的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignorespace</span></span></code></pre></div><p>现在，如果你输入以空格开头的命令，那么它将不会记录在历史记录中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;hello&quot;</span></span>
<span class="line"><span>$     mysql -u bogus -h badpassword123 mydatabase</span></span>
<span class="line"><span>$ echo &quot;world&quot;</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  echo &quot;hello&quot;</span></span>
<span class="line"><span>  2  echo &quot;world&quot;</span></span>
<span class="line"><span>  3  history</span></span></code></pre></div><p>你也可以避免重复的条目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignoredups</span></span></code></pre></div><p>现在，如果你一个接着一个输入两个命令，历史记录中只会显示一个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>  1  ls</span></span>
<span class="line"><span>  2  history</span></span></code></pre></div><p>如果你喜欢这两个忽略功能，那么可以使用 <code>ignoreboth</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL=$HISTCONTROL:ignoreboth</span></span></code></pre></div><h3 id="从历史记录中删除命令" tabindex="-1">从历史记录中删除命令 <a class="header-anchor" href="#从历史记录中删除命令" aria-label="Permalink to “从历史记录中删除命令”">​</a></h3><p>有时你会犯一个错误，在 shell 中输入了一些敏感内容，或者你​​只是想清理历史记录，以便它更准确地表示让某件事正常工作所采取的步骤。如果要从 Bash 的历史记录中删除命令，请在要删除的项目的行号上使用 <code>-d</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;foo&quot;</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>$ echo &quot;bar&quot;</span></span>
<span class="line"><span>bar</span></span>
<span class="line"><span>$ history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  echo &quot;bar&quot;</span></span>
<span class="line"><span>  537  history | tail</span></span>
<span class="line"><span>$ history -d 536</span></span>
<span class="line"><span>$ history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  history | tail</span></span>
<span class="line"><span>  537  history -d 536</span></span>
<span class="line"><span>  538  history | tail</span></span></code></pre></div><p>要停止添加 <code>history</code> 条目，只要在 <code>HISTCONTROL</code> 环境变量中有 <code>ignorespace</code>，就可以在命令前添加空格：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$  history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span>
<span class="line"><span>  536  echo &quot;bar&quot;</span></span>
<span class="line"><span>$  history -d 536</span></span>
<span class="line"><span>$  history | tail</span></span>
<span class="line"><span>  535  echo &quot;foo&quot;</span></span></code></pre></div><p>你可以使用 <code>-c</code> 选项清除所有会话历史记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history -c</span></span>
<span class="line"><span>$  history</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="history-命令的经验" tabindex="-1">history 命令的经验 <a class="header-anchor" href="#history-命令的经验" aria-label="Permalink to “history 命令的经验”">​</a></h3><p>操纵历史通常没有听起来那么危险，尤其是当你有目标地管理它时。例如，如果你要记录一个复杂的问题，通常最好使用会话历史来记录命令，因为通过将命令插入历史记录，你能运行它们并从而测试过程。很多时候，不执行历史命令会导致忽略小的步骤或写错小细节。</p><p>按需使用历史会话，并明智地控制历史记录。享受历史修改吧！</p><hr>`,27)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/20/6/bash-history-control"},{default:t(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/20/6/bash-history-control",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[7]||(s[7]=[a("Seth Kenlon",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const T=p(d,[["render",u]]);export{C as __pageData,T as default};
